<?php
require __DIR__ . '/bootstrap.php';
require __DIR__ . '/services.php';
$user = require_roles(['admin','operator']); $row = teacher_row(request_id(),$user);
$students = query('SELECT s.id,s.last_name,s.first_name FROM students s JOIN student_teacher st ON st.student_id=s.id WHERE st.teacher_id=? ORDER BY s.id',[$row['id']])->fetchAll();
page_header('講師詳細','teachers');
?><div class="form-panel"><a class="back-link" href="teachers.php">← 講師一覧へ戻る</a><section class="panel"><div class="form-title"><span class="eyebrow">講師情報</span><h1><?=e(full_name($row))?></h1></div><dl class="detail-grid"><div><dt class="detail-label">姓</dt><dd class="detail-value"><?=e($row['last_name'])?></dd></div><div><dt class="detail-label">名</dt><dd class="detail-value"><?=e($row['first_name'])?></dd></div><div><dt class="detail-label">メールアドレス</dt><dd class="detail-value"><?=e($row['email'])?></dd></div><div><dt class="detail-label">権限</dt><dd class="detail-value"><span class="role <?=e($row['role'])?>"><?=e($row['role'])?></span> <?=e(role_label($row['role']))?></dd></div><div class="span-two"><dt class="detail-label">担当生徒（<?=count($students)?>名）</dt><dd class="detail-value assignment-list"><?php foreach ($students as $student): ?><a class="tag" href="student_detail.php?id=<?=(int)$student['id']?>"><?=e(full_name($student))?></a><?php endforeach; ?><?php if (!$students): ?>担当生徒はいません。<?php endif; ?></dd></div><div class="span-two"><dt class="detail-label">特記事項</dt><dd class="detail-value notes"><?=e($row['notes']?:'登録されていません。')?></dd></div></dl><div class="actions"><a class="button secondary" href="teachers.php">一覧へ戻る</a><?php if ($user['role']==='admin'): ?><a class="button" href="teacher_edit.php?id=<?=(int)$row['id']?>">講師情報を編集</a><?php endif; ?></div></section></div><?php page_footer(); ?>
